numbers = [29, 10, 14, 37, 13]

items = list(numbers)
for i in range(len(items) - 1):
    smallest = i
    for j in range(i + 1, len(items)):          # find the minimum of the unsorted part
        if items[j] < items[smallest]:
            smallest = j
    if smallest != i:
        items[i], items[smallest] = items[smallest], items[i]
        print("Step", i + 1, ": swap", items[i], "and", items[smallest], "->", items)
    else:
        print("Step", i + 1, ":", items[i], "already in place ->", items)
print("Sorted:", items)
